import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void mse_loss_kernel(const half* predictions, const half* targets, half* output, int64_t total_elements) {
    extern __shared__ half sdata[];

    int tid = threadIdx.x;
    int bid = blockIdx.x;
    int block_size = blockDim.x;

    // Each thread processes multiple elements
    half sum = __float2half(0.0f);
    int start_idx = bid * block_size + tid;

    // Process elements with grid-stride loop
    for (int i = start_idx; i < total_elements; i += gridDim.x * block_size) {
        half diff = predictions[i] - targets[i];
        sum = __hadd(sum, __hmul(diff, diff));
    }

    sdata[tid] = sum;
    __syncthreads();

    // Reduction within block
    for (int s = block_size / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = __hadd(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }

    // Write block result to global memory
    if (tid == 0) {
        atomicAdd(output, sdata[0]);
    }
}

__global__ void mse_loss_finalize_kernel(half* output, int64_t total_elements) {
    if (threadIdx.x == 0 && blockIdx.x == 0) {
        *output = __hdiv(*output, __float2half(static_cast<float>(total_elements)));
    }
}
"""

def compile_and_run():
    # Create the CUDA extension
    module = load_inline(
        name="mse_loss_ext",
        cpp_sources="",
        cuda_sources=cuda_source,
        functions=["mse_loss_kernel", "mse_loss_finalize_kernel"],
        verbose=True
    )

    class ModelNew(torch.nn.Module):
        def __init__(self):
            super(ModelNew, self).__init__()

        def forward(self, predictions, targets):
            # Ensure inputs are contiguous and have correct dtype
            predictions = predictions.contiguous().to(torch.float16)
            targets = targets.contiguous().to(torch.float16)

            # Get total number of elements
            total_elements = predictions.numel()

            # Allocate output tensor
            output = torch.zeros(1, dtype=torch.float16, device=predictions.device)

            # Configure kernel launch parameters
            block_size = 256
            grid_size = min(65535, (total_elements + block_size - 1) // block_size)

            # Launch reduction kernel
            shared_mem_size = block_size * sizeof(half)
            module.mse_loss_kernel(
                predictions.data_ptr(),
                targets.data_ptr(),
                output.data_ptr(),
                total_elements,
                block=(block_size, 1, 1),
                grid=(grid_size, 1, 1),
                shared_mem=shared_mem_size
            )

            # Finalize by dividing by total elements
            module.mse_loss_finalize_kernel(
                output.data_ptr(),
                total_elements,
                block=(1, 1, 1),
                grid=(1, 1, 1)
            )

            return output

    return ModelNew

